4.4 Write growth summaries to disc
streptomycin_ug_ml is carried into the summary table here — upstream it was a constant 0 and could be dropped.


Show/hide code
myformatter &lt;- function(df, grvar) {
  df |&gt;
    dplyr::select(
      species = strainID,
      evo_hist,
      streptomycin_ug_ml,
      carbon_source,
      carbon_class = class,
      {{ grvar }}
    ) |&gt;
    mutate(
      genotype = str_sub(evo_hist, 1, 1),
    ) |&gt;
    arrange(
      species,
      genotype,
      streptomycin_ug_ml,
      carbon_source,
      carbon_class
    ) |&gt;
    group_by(
      species,
      genotype,
      streptomycin_ug_ml,
      carbon_source,
      carbon_class
    ) |&gt;
    mutate(replicate = LETTERS[1:n()]) |&gt;
    ungroup() |&gt;
    dplyr::select(
      species,
      genotype,
      streptomycin_ug_ml,
      carbon_source,
      carbon_class,
      replicate,
      {{ grvar }}
    )
}

left_join(myformatter(gr_per_well, mumax), myformatter(k_per_well, max_od)) |&gt;
  left_join(myformatter(auc_per_well, auc)) |&gt;
  rename(
    growth_rate = mumax,
    carrying_capacity = max_od,
    area_under_growth_curve = auc
  ) |&gt;
  write_tsv(here::here(data_processed, "growth_summaries_carbon.tsv"))

