2.2 Cell access


Show/hide code
read_cell_matrices &lt;- function(path) {
  cells &lt;- tidyxl::xlsx_cells(path, sheets = 1)
  max_row &lt;- max(cells$row)
  max_col &lt;- max(cells$col)

  num_mat &lt;- matrix(NA_real_, nrow = max_row, ncol = max_col)
  chr_mat &lt;- matrix(NA_character_, nrow = max_row, ncol = max_col)
  idx &lt;- as.matrix(cells[c("row", "col")])
  num_mat[idx] &lt;- cells$numeric
  chr_mat[idx] &lt;- cells$character

  list(num = num_mat, chr = chr_mat, max_row = max_row, max_col = max_col)
}

# Returns the numeric value if present, otherwise the character value. Scalar
# by necessity: the two matrices have different types.
cell_value &lt;- function(mats, row, col) {
  out_of_range &lt;- row &lt; 1 || row &gt; mats$max_row || col &lt; 1 || col &gt; mats$max_col
  if (out_of_range) {
    return(NA)
  }
  num_val &lt;- mats$num[row, col]
  if (is.na(num_val)) mats$chr[row, col] else num_val
}

2.3 Merged cell resolution


Show/hide code
read_merge_ranges &lt;- function(path, mats) {
  wb &lt;- openxlsx::loadWorkbook(path)
  refs &lt;- stringr::str_match(wb$worksheets[[1]]$mergeCells, 'ref="([^"]+)"')[,
    2
  ]

  refs |&gt;
    stringr::str_split(":") |&gt;
    purrr::map(\(parts) {
      rows &lt;- as.integer(stringr::str_extract(parts, "[0-9]+"))
      cols &lt;- purrr::map_int(
        stringr::str_extract(parts, "[A-Z]+"),
        openxlsx::convertFromExcelRef
      )
      tibble::tibble(
        min_row = min(rows),
        max_row = max(rows),
        col = seq(min(cols), max(cols)),
        top_val = cell_value(mats, min(rows), min(cols))
      )
    }) |&gt;
    purrr::list_rbind()
}

# For one sheet row, return the carbon source per well-column, preferring a
# merged-block value over the bare cell.
resolve_merged_row &lt;- function(mats, merges, row, cols) {
  merged &lt;- merges |&gt;
    dplyr::filter(min_row &lt;= row, row &lt;= max_row, col %in% cols) |&gt;
    dplyr::distinct(col, .keep_all = TRUE)

  tibble::tibble(col = cols) |&gt;
    dplyr::mutate(
      bare_val = purrr::map_chr(
        col,
        \(cl) as.character(cell_value(mats, row, cl))
      )
    ) |&gt;
    dplyr::left_join(dplyr::select(merged, col, top_val), by = "col") |&gt;
    dplyr::mutate(
      carbon_source = dplyr::coalesce(as.character(top_val), bare_val)
    ) |&gt;
    dplyr::select(col, carbon_source)
}

2.4 Value cleaning


Show/hide code
clean_carbon_source &lt;- function(x) {
  x &lt;- stringr::str_trim(as.character(x))
  dplyr::case_when(
    is.na(x) ~ "",
    stringr::str_to_lower(x) == "control" ~ "Control",
    .default = x |&gt;
      stringr::str_remove_all(stringr::fixed("M9MM with ")) |&gt;
      stringr::str_remove_all(stringr::fixed(" + Str"))
  )
}

format_streptomycin &lt;- function(x) {
  x &lt;- suppressWarnings(as.numeric(x))
  dplyr::case_when(
    is.na(x) ~ "",
    x == round(x) ~ sprintf("%.1f", x),
    .default = format(x, trim = TRUE, scientific = FALSE)
  )
}

# Strain labels look like "ANC1977" / "EVO1287"; anything else (e.g. "Control")
# is passed through as evo_hist with an empty strainID.
parse_evo_hist &lt;- function(x) {
  dplyr::coalesce(
    stringr::str_extract(as.character(x), "^(ANC|EVO)"),
    as.character(x)
  )
}

parse_strain_id &lt;- function(x) {
  dplyr::coalesce(
    stringr::str_match(as.character(x), "^(?:ANC|EVO)(\\d+)")[, 2],
    ""
  )
}

2.5 Parsing


Show/hide code
parse_plate_block &lt;- function(
  mats,
  merges,
  plate,
  medium_row,
  well_cols,
  row_rows,
  strep_row
) {
  carbon_by_col &lt;- resolve_merged_row(
    mats,
    merges,
    medium_row,
    well_cols$col
  )

  tidyr::expand_grid(
    sheet_row = row_rows,
    col = well_cols$col
  ) |&gt;
    dplyr::left_join(well_cols, by = "col") |&gt;
    dplyr::left_join(carbon_by_col, by = "col") |&gt;
    dplyr::mutate(
      plate = plate,
      row = purrr::map_chr(
        sheet_row,
        \(r) as.character(cell_value(mats, r, 2))
      ),
      strain = purrr::map2_chr(
        sheet_row,
        col,
        \(r, cl) as.character(cell_value(mats, r, cl))
      ),
      strep = purrr::map_chr(
        col,
        \(cl) as.character(cell_value(mats, strep_row, cl))
      ),
      well = stringr::str_c(row, well_column),
      evo_hist = parse_evo_hist(strain),
      strainID = parse_strain_id(strain),
      streptomycin_ug_ml = format_streptomycin(strep),
      carbon_source = clean_carbon_source(carbon_source)
    ) |&gt;
    dplyr::select(
      plate,
      well,
      row,
      column = well_column,
      evo_hist,
      strainID,
      streptomycin_ug_ml,
      carbon_source
    )
}

# Locate the sheet rows that start each plate block.
find_plate_header_rows &lt;- function(mats) {
  seq_len(mats$max_row) |&gt;
    purrr::keep(\(r) {
      v &lt;- cell_value(mats, r, 1)
      is.character(v) &&
        !is.na(v) &&
        stringr::str_starts(stringr::str_trim(v), "Plate")
    })
}

# The data rows of a block run from just below the header until column B is
# empty; the medium and streptomycin rows follow immediately after.
block_layout &lt;- function(mats, header_row) {
  row_rows &lt;- integer(0)
  rr &lt;- header_row + 1
  while (rr &lt;= mats$max_row && !is.na(cell_value(mats, rr, 2))) {
    row_rows &lt;- c(row_rows, rr)
    rr &lt;- rr + 1
  }
  list(row_rows = row_rows, medium_row = rr, strep_row = rr + 1)
}

parse_platemap &lt;- function(xlsx_path) {
  mats &lt;- read_cell_matrices(xlsx_path)
  merges &lt;- read_merge_ranges(xlsx_path, mats)

  find_plate_header_rows(mats) |&gt;
    purrr::map(\(header_row) {
      layout &lt;- block_layout(mats, header_row)

      well_cols &lt;- tibble::tibble(col = seq(3, mats$max_col)) |&gt;
        dplyr::mutate(
          well_column = purrr::map_dbl(
            col,
            \(cl) suppressWarnings(as.numeric(cell_value(mats, header_row, cl)))
          )
        ) |&gt;
        dplyr::filter(!is.na(well_column)) |&gt;
        dplyr::mutate(well_column = as.integer(well_column))

      parse_plate_block(
        mats = mats,
        merges = merges,
        plate = stringr::str_trim(cell_value(mats, header_row, 1)),
        medium_row = layout$medium_row,
        well_cols = well_cols,
        row_rows = layout$row_rows,
        strep_row = layout$strep_row
      )
    }) |&gt;
    purrr::list_rbind()
}
